pub fn is_prime(n: i8) -> bool {
    // By definition, primes are >= 2.
    if n < 2 {
        return false;
    }
    // Now n is in [2..127]. Try all divisors k in [2..n).
    let mut k: i8 = 2;
    while k < n {
        if n % k == 0 {
            return false;
        }
        k += 1;
    }
    true
}

